-- Переводы строк, появившихся в 6.2.16 - 6.3.0 (добавляются в ruRU.lua через tools/ru/sync_ui.py --add).
  ["Thank emote"] = "Эмоция благодарности",
  ["Empty = /thank. Or another emote (/hello) or your own text (/emote says thank you, %n!)."] = "Пусто = /thank. Или другая эмоция (/hello) либо свой текст (/emote благодарит %n!).",
  ["An emote command like /hello, /bow or /cheer is done at the player. /emote, /e, /me or text without a slash becomes an emote line in the chat; %n is the player's name."] = "Команда эмоции вроде /hello, /bow или /cheer применяется к игроку. /emote, /e, /me или текст без слэша отправляются в чат как строка эмоции; %n — имя игрока.",
  ["Unknown emote: %s - /thank is used instead."] = "Неизвестная эмоция: %s — вместо нее используется /thank.",
  ["Group invites, thanks for buffs, duels and recipe sharing."] = "Приглашения в группу, благодарность за баффы, дуэли и обмен рецептами.",
  ["Thanks"] = "Благодарность",
  ["Show weapon skill-ups"] = "Показывать рост оружейных навыков",
  ["Weapon and Defense skill increases."] = "Повышение навыков владения оружием и защиты.",
  ["Show profession skill-ups"] = "Показывать рост навыков профессий",
  ["Skill increases of your professions, also Cooking, First Aid and Fishing."] = "Повышение навыков ваших профессий, а также Кулинарии, Первой помощи и Рыбной ловли.",
  ["Request stop"] = "Запросить остановку",
  ["Land at the next flight master on the route."] = "Приземлиться у следующего распорядителя полетов по маршруту.",
  ["Landing at the next flight master"] = "Посадка у следующего распорядителя полетов",
  ["Landing at %s"] = "Посадка в %s",
  ["Next: %s"] = "Далее: %s",
  ["Right-click: add to wishlist"] = "Правый щелчок: добавить в список желаний",
  ["Right-click: remove from wishlist"] = "Правый щелчок: убрать из списка желаний",
  ["CPU check: type /console scriptProfile 1, then /reload, play a few minutes and type /ofa cpu again. Turn it off afterwards with /console scriptProfile 0 and /reload."] = "Проверка CPU: введите /console scriptProfile 1, затем /reload, поиграйте пару минут и снова введите /ofa cpu. После этого выключите через /console scriptProfile 0 и /reload.",
  ["%s from %s: %s"] = "%s от %s: %s",
  ["Follow-up of The Honor of the Kor'kron."] = "Продолжение задания «Честь кор'кронов».",
  ["Follow-up of Bad News for Folkar."] = "Продолжение задания «Дурные вести».",
  ["Follow-up of the first quest of the same name."] = "Продолжение первого задания с тем же названием.",
  ["Find Herbs shows herbs on your minimap - switch it on in the spellbook; it ends when you die."] = "«Поиск трав» показывает травы на миникарте — включите его в книге заклинаний; эффект спадает после смерти.",
  ["Herbs come back fast in the starting zones - pick what you pass."] = "В стартовых зонах травы появляются быстро — собирайте все, что попадется по пути.",
  ["Darkshore has the most herbs; small loops are enough."] = "Больше всего трав на Темных берегах; достаточно небольших кругов.",
  ["Learn Artisan at 200 before you go - neither zone has a trainer."] = "Изучите ранг «Мастеровой» на 200 до отправки — ни в одной из этих двух зон нет учителя.",
  ["Ghost Mushrooms grow in caves and need 245."] = "Призрачные поганки растут в пещерах и требуют навык 245.",
  ["Find Minerals shows ore veins on your minimap - switch it on in the spellbook; it ends when you die."] = "«Поиск минералов» показывает рудные жилы на миникарте — включите его в книге заклинаний; эффект спадает после смерти.",
  ["Smelt your copper at the next forge after every lap - smelting gives points too."] = "Переплавляйте медь у ближайшей кузни после каждого круга — выплавка тоже дает очки навыка.",
  ["Make your Bronze Bars before you leave: Bronze gives points only up to about 105."] = "Сделайте бронзовые слитки до ухода: бронза дает очки только примерно до 105.",
  ["Riverglades is full of Iron Deposits; leave its caves to higher levels."] = "В Лесоречье полно залежей железа; его пещеры лучше оставить для высоких уровней.",
  ["Some caves there hold level 60 elites."] = "В некоторых тамошних пещерах обитают элитные враги 60-го уровня.",
  ["Rich Thorium Veins need 275."] = "Богатые ториевые жилы требуют навык 275.",
  ["From 138 to 155 no smelting gives points - mine Iron there."] = "С 138 по 155 выплавка не дает очков — добывайте там железо.",
  ["You can skin a beast up to level 10 from the start; then you need 10 skill per level up to level 20 and five times its level after that."] = "Снимать шкуры с животных до 10-го уровня можно с самого начала; затем до 20-го уровня нужно 10 навыка за каждый уровень, а выше — в пять раз больше уровня существа.",
  ["Every beast of the starting zones counts up to 75."] = "Подойдет любое животное в стартовых зонах вплоть до 75.",
  ["The raptor camp west of Northwatch Hold respawns fast and carries you to 150."] = "Лагерь ящеров к западу от крепости Северной Стражи быстро возрождается и доведет вас до 150.",
  ["The yetis in the Hillsbrad cave respawn quickly - you can stay inside."] = "Йети в пещере Предгорий Хилсбрада быстро возрождаются — можно не выходить наружу.",
  ["Learn Artisan at 200; the Hulking Feral Scars need 230."] = "Изучите ранг «Мастеровой» на 200; для самых крупных йети там (46-й ур.) нужен навык 230.",
  ["The fish you catch level Cooking too - every step shows what to cook with it."] = "Пойманная рыба также качает Кулинарию — на каждом этапе показано, что из нее приготовить.",
  ["Any lake or river of a starting zone. Keep the fish for Cooking."] = "Любое озеро или река стартовой зоны. Сохраняйте рыбу для Кулинарии.",
  ["Learn Journeyman Fishing at 50 (level 10) at your fishing trainer."] = "Изучите «Рыбная ловля (Подмастерье)» на навыке 50 (10-й ур.) у учителя рыбной ловли.",
  ["Expert Fishing (from 125, level 20) is a book from Old Man Heming in Booty Bay. Read the Expert Cookbook at Cooking 125."] = "«Умелец» для рыбной ловли (от 125, 20-й ур.) изучается по книге у Старика Хеминга в Пиратской бухте. Кулинарную книгу умельца прочтите на Кулинарии 125.",
  ["Fish the swamp water, not the sea. At 225 Nat Pagle in Dustwallow Marsh gives the Artisan quest; the Artisan Cooking quest is in Gadgetzan."] = "Ловите в болотной воде, а не в море. На 225 Нат Пэгл в Пылевых топях выдает задание на ранг «Мастеровой»; задание на ранг «Мастеровой» в Кулинарии — в Прибамбасске.",
  ["Use Bright Baubles or most fish get away. Nightfin Snappers do not bite between 12:00 and 18:00 (game time)."] = "Используйте Яркие блесны, иначе большая часть рыбы сорвется. Черноперый луциан не клюет с 12:00 до 18:00 (игрового времени).",
  ["Your Lockpicking can be at most five times your level."] = "Ваш навык Взлома замков не может превышать ваш уровень более чем в пять раз.",
  ["The strongboxes on the ship near Ratchet respawn in seconds; the chest at the bottom spawns a strong enemy."] = "Сейфы на корабле рядом с Кабестаном появляются снова за пару секунд; сундук на самом дне призывает сильного врага.",
  ["Zoram Strand: footlockers on the shore, the ones in the water from 110."] = "Зорамское взморье: сундучки на берегу, те что в воде — с навыка 110.",
  ["Angor Fortress: upstairs first, downstairs from 175."] = "Крепость Ангор: сначала наверху, с 175 спускайтесь вниз.",
  ["The Slag Pit in Searing Gorge, or Lost Rigger Cove in Tanaris."] = "Шлаковая яма в Тлеющем ущелье или Бухта Сорванного Паруса в Танарисе.",
